function topThreeWindows(nums: number[], k: number): number[] {
  const m = nums.length - k + 1, W: number[] = [];
  for (let i = 0; i < m; i++) {
    let s = 0;
    for (let t = i; t < i + k; t++) s += nums[t];
    W.push(s);
  }
  let best = -1, ans: number[] = [];
  for (let a = 0; a < m; a++)
    for (let b = a + k; b < m; b++)
      for (let c = b + k; c < m; c++)
        if (W[a] + W[b] + W[c] > best) { best = W[a] + W[b] + W[c]; ans = [a, b, c]; }
  return ans;
}

