function topThreeWindows(nums: number[], k: number): number[] {
  const n = nums.length, m = n - k + 1;
  const W = new Array(m).fill(0);
  let s = 0;
  for (let i = 0; i < n; i++) {
    s += nums[i];
    if (i >= k) s -= nums[i - k];
    if (i >= k - 1) W[i - k + 1] = s;
  }
  const left = new Array(m).fill(0), right = new Array(m).fill(m - 1);
  for (let i = 1; i < m; i++) left[i] = W[i] > W[left[i - 1]] ? i : left[i - 1];
  for (let i = m - 2; i >= 0; i--) right[i] = W[i] >= W[right[i + 1]] ? i : right[i + 1];
  let best = -1, ans: number[] = [];
  for (let j = k; j + k < m; j++) {
    const a = left[j - k], c = right[j + k];
    const total = W[a] + W[j] + W[c];
    if (total > best) { best = total; ans = [a, j, c]; }
  }
  return ans;
}

