class Solution:
    def topThreeWindows(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        m = n - k + 1
        W = [0] * m
        s = 0
        for i, v in enumerate(nums):
            s += v
            if i >= k:
                s -= nums[i - k]
            if i >= k - 1:
                W[i - k + 1] = s
        left, right = [0] * m, [m - 1] * m
        for i in range(1, m):
            left[i] = i if W[i] > W[left[i - 1]] else left[i - 1]
        for i in range(m - 2, -1, -1):
            right[i] = i if W[i] >= W[right[i + 1]] else right[i + 1]
        best, ans = -1, []
        for j in range(k, m - k):
            a, c = left[j - k], right[j + k]
            total = W[a] + W[j] + W[c]
            if total > best:
                best, ans = total, [a, j, c]
        return ans

